export function battleTypePositions(side,art){
 const types=battleArtTypes[art]??[];
 return types.map((type,i)=>({type,x:side?224+i*18:136-types.length*18+2+i*18,y:64}));
}
export function drawBattleTypes(ctx,side,art){
 for(const {type,x,y} of battleTypePositions(side,art))drawTypeIcon(ctx,type,x,y);
}
export function drawTypeIcon(ctx,type,x,y){
 ctx.save();
  const [color,mark]=icons[type];
  for(let row=0;row<16;row++)for(let col=0;col<16;col++){
   const d=(2*col-15)**2+(2*row-15)**2;if(d>225)continue;
   ctx.fillStyle=d>173?'#152c3c':col>=3&&col<13&&row>=3&&row<13&&mark[row-3][col-3]==='#'?'#f6f0d8':'#'+color;
   ctx.fillRect(x+col,y+row,1,1);
  }
 ctx.restore();
}
